"""Infix to Postfix notation converter using the Shunting Yard algorithm."""

import unittest


def infix_to_postfix(expression: str) -> str:
    """Convert an infix expression to postfix (Reverse Polish) notation.

    Supports operators: +, -, *, /, ^ (exponentiation)
    Supports parentheses for grouping.
    Operands can be single-letter variables or multi-digit numbers.

    Args:
        expression: A string infix expression, e.g. "A + B * C"

    Returns:
        The equivalent postfix expression as a string.

    Raises:
        ValueError: On mismatched parentheses or invalid tokens.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    right_associative = {'^'}

    output: list[str] = []
    op_stack: list[str] = []
    tokens = _tokenize(expression)

    for token in tokens:
        if _is_operand(token):
            output.append(token)
        elif token == '(':
            op_stack.append(token)
        elif token == ')':
            while op_stack and op_stack[-1] != '(':
                output.append(op_stack.pop())
            if not op_stack:
                raise ValueError("Mismatched parentheses: unmatched ')'")
            op_stack.pop()  # discard '('
        elif token in precedence:
            while (
                op_stack
                and op_stack[-1] != '('
                and op_stack[-1] in precedence
                and (
                    precedence[op_stack[-1]] > precedence[token]
                    or (
                        precedence[op_stack[-1]] == precedence[token]
                        and token not in right_associative
                    )
                )
            ):
                output.append(op_stack.pop())
            op_stack.append(token)
        else:
            raise ValueError(f"Unknown token: {token}")

    while op_stack:
        top = op_stack.pop()
        if top == '(':
            raise ValueError("Mismatched parentheses: unmatched '('")
        output.append(top)

    return ' '.join(output)


def _tokenize(expression: str) -> list[str]:
    """Split an expression string into tokens (numbers, variables, operators, parens)."""
    tokens: list[str] = []
    i = 0
    while i < len(expression):
        ch = expression[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            j = i
            while j < len(expression) and expression[j].isdigit():
                j += 1
            tokens.append(expression[i:j])
            i = j
        elif ch.isalpha():
            j = i
            while j < len(expression) and expression[j].isalnum():
                j += 1
            tokens.append(expression[i:j])
            i = j
        elif ch in '+-*/^()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch}")
    return tokens


def _is_operand(token: str) -> bool:
    """Return True if the token is an operand (number or variable name)."""
    return token.isalnum()


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

class TestInfixToPostfix(unittest.TestCase):

    # --- basic cases ---

    def test_single_operand(self):
        self.assertEqual(infix_to_postfix("A"), "A")

    def test_single_number(self):
        self.assertEqual(infix_to_postfix("42"), "42")

    def test_simple_addition(self):
        self.assertEqual(infix_to_postfix("A + B"), "A B +")

    def test_simple_subtraction(self):
        self.assertEqual(infix_to_postfix("X - Y"), "X Y -")

    def test_simple_multiplication(self):
        self.assertEqual(infix_to_postfix("A * B"), "A B *")

    def test_simple_division(self):
        self.assertEqual(infix_to_postfix("A / B"), "A B /")

    # --- precedence ---

    def test_multiply_before_add(self):
        # A + B * C  =>  A B C * +
        self.assertEqual(infix_to_postfix("A + B * C"), "A B C * +")

    def test_multiply_before_add_reversed(self):
        # A * B + C  =>  A B * C +
        self.assertEqual(infix_to_postfix("A * B + C"), "A B * C +")

    def test_divide_before_subtract(self):
        self.assertEqual(infix_to_postfix("A - B / C"), "A B C / -")

    def test_all_operators(self):
        # A + B * C - D / E  =>  A B C * + D E / -
        self.assertEqual(infix_to_postfix("A + B * C - D / E"), "A B C * + D E / -")

    def test_exponentiation(self):
        # A ^ B ^ C is right-associative: A B C ^ ^
        self.assertEqual(infix_to_postfix("A ^ B ^ C"), "A B C ^ ^")

    def test_exponentiation_left_context(self):
        # A * B ^ C  =>  A B C ^ *
        self.assertEqual(infix_to_postfix("A * B ^ C"), "A B C ^ *")

    # --- parentheses ---

    def test_parentheses_override(self):
        # (A + B) * C  =>  A B + C *
        self.assertEqual(infix_to_postfix("(A + B) * C"), "A B + C *")

    def test_nested_parentheses(self):
        # ((A + B) * (C - D))  =>  A B + C D - *
        self.assertEqual(infix_to_postfix("((A + B) * (C - D))"), "A B + C D - *")

    def test_deeply_nested(self):
        # (A + (B * (C ^ D)))  =>  A B C D ^ * +
        self.assertEqual(infix_to_postfix("(A + (B * (C ^ D)))"), "A B C D ^ * +")

    def test_parentheses_around_single(self):
        self.assertEqual(infix_to_postfix("(A)"), "A")

    # --- multi-character operands ---

    def test_multi_digit_number(self):
        self.assertEqual(infix_to_postfix("12 + 34"), "12 34 +")

    def test_multi_char_variable(self):
        self.assertEqual(infix_to_postfix("abc + def"), "abc def +")

    def test_alphanumeric_variable(self):
        self.assertEqual(infix_to_postfix("x1 + y2"), "x1 y2 +")

    # --- complex expressions ---

    def test_complex_expression(self):
        # A + B * (C - D) / E ^ F
        # =>  A B C D - * E F ^ / +
        result = infix_to_postfix("A + B * (C - D) / E ^ F")
        self.assertEqual(result, "A B C D - * E F ^ / +")

    def test_expression_from_classic_example(self):
        # (A + B) * C - (D - E) * (F + G)
        # =>  A B + C * D E - F G + * -
        result = infix_to_postfix("(A + B) * C - (D - E) * (F + G)")
        self.assertEqual(result, "A B + C * D E - F G + * -")

    def test_chained_same_precedence(self):
        # A + B - C + D  =>  A B + C - D +
        self.assertEqual(infix_to_postfix("A + B - C + D"), "A B + C - D +")

    def test_chained_multiplication(self):
        # A * B / C * D  =>  A B * C / D *
        self.assertEqual(infix_to_postfix("A * B / C * D"), "A B * C / D *")

    # --- whitespace variations ---

    def test_no_whitespace(self):
        self.assertEqual(infix_to_postfix("A+B*C"), "A B C * +")

    def test_extra_whitespace(self):
        self.assertEqual(infix_to_postfix("  A   +  B  *  C  "), "A B C * +")

    def test_tabs(self):
        self.assertEqual(infix_to_postfix("A\t+\tB"), "A B +")

    # --- error cases ---

    def test_unmatched_close_paren(self):
        with self.assertRaises(ValueError):
            infix_to_postfix("A + B)")

    def test_unmatched_open_paren(self):
        with self.assertRaises(ValueError):
            infix_to_postfix("(A + B")

    def test_empty_expression(self):
        self.assertEqual(infix_to_postfix(""), "")

    def test_whitespace_only(self):
        self.assertEqual(infix_to_postfix("   "), "")

    def test_invalid_character(self):
        with self.assertRaises(ValueError):
            infix_to_postfix("A $ B")

    # --- numbers in complex expressions ---

    def test_numbers_and_operators(self):
        self.assertEqual(infix_to_postfix("3 + 4 * 2"), "3 4 2 * +")

    def test_number_with_parentheses(self):
        self.assertEqual(infix_to_postfix("(1 + 2) * 3"), "1 2 + 3 *")


if __name__ == '__main__':
    unittest.main()
